import { MATERIAL_FAMILIES, MATERIAL_IDS } from '../material';

export const MATERIAL_MIGRATION = '20261024195916_material.sql';

const lit = (v: string): string => `'${v.replaceAll("'", "''")}'`;

function pieceColumn(table: string): string {
  return `alter table app.${table}
  add column material text constraint ${table}_material_check
    check (material in (${MATERIAL_IDS.map(lit).join(', ')}));`;
}

// The material column (legacy 2026-10-24): generated so the check list is the model's.
export function materialModelSql(): string {
  return `-- migrate:up
-- GENERATED by packages/core (pnpm --filter @robes/core gen:sql); edit the TS sources, never this file.
-- The material model (legacy 2026-10-24, "Colour & material, one section"): ONE material per piece,
-- the one it is mostly made of, from ${MATERIAL_FAMILIES.length} families and ${MATERIAL_IDS.length} materials. Null = not filed. The
-- family is derived from the id, never stored. Robes' "check it" flag rides item_dna.material_check.
${pieceColumn('wardrobe_items')}

${pieceColumn('wishlist_items')}

-- migrate:down
-- Forward-only: fix mistakes with a new migration.
`;
}
